UPDATE biz_collab_room SET last_callback_type = #{callbackType}, last_callback_status = #{callbackStatus},
    last_wps_request_id = #{wpsRequestId}, last_error_message = #{errorMessage}, update_time = #{updateTime}
WHERE room_id = #{roomId}

UPDATE biz_collab_upload_ticket SET status = 'UPLOADED', uploaded_file_size = #{uploadedFileSize},
    uploaded_sha256 = #{uploadedSha256}, update_time = #{updateTime}
WHERE ticket_token = #{ticketToken} AND status = 'PREPARED' AND expires_time > #{updateTime}

UPDATE biz_collab_upload_ticket SET status = #{status}, completed_time = #{completedTime},
    error_message = #{errorMessage}, update_time = #{completedTime}
WHERE ticket_id = #{ticketId} AND status IN ('PREPARED', 'UPLOADED')
